/usr/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict';
import { createProgressFeed, createTransferWorkspace, collectProgressTelemetry } from './src/workspace.js';
const pending = new Map();
const feed = createProgressFeed({ initialPacket: 'initial', decode: packet => packet === 'initial' ? 'initial' : new Promise(resolve => pending.set(packet, resolve)) });
const shown = [], recorded = [], deltas = [];
const stopTelemetry = collectProgressTelemetry(feed, frame => deltas.push(frame));
const workspace = createTransferWorkspace({ transport() {}, onCancel() {}, record() {}, showQueued() {}, recordProgress: x => recorded.push(x.frame), showProgress: x => shown.push(x.frame) });
workspace.select({ id: 'a', progressFeed: feed });
assert.deepEqual(shown, ['initial']);
assert.deepEqual(recorded, ['initial']);
assert.deepEqual(deltas, []);
feed.emit('older'); feed.emit('newer');
pending.get('newer')('newer'); await Promise.resolve();
pending.get('older')('older'); await Promise.resolve();
assert.deepEqual(shown, ['initial', 'newer']);
assert.deepEqual(recorded, ['initial', 'newer', 'older']);
assert.deepEqual(deltas, ['newer', 'older']);
workspace.hide(); stopTelemetry();
console.log('progress smoke checks passed');
EOF"

